create extension if not exists pgcrypto;
create table if not exists public.directions(id uuid primary key default gen_random_uuid(),title text not null,description text,icon text,published boolean default true,sort_order int default 0);
create table if not exists public.education(id uuid primary key default gen_random_uuid(),period text,title text not null,description text,sort_order int default 0);
create table if not exists public.menu_items(id uuid primary key default gen_random_uuid(),label text not null,href text not null,visible boolean default true,sort_order int default 0);
create table if not exists public.patient_resources(id uuid primary key default gen_random_uuid(),title text not null,type text,url text,published boolean default true,sort_order int default 0);
create table if not exists public.reply_templates(id uuid primary key default gen_random_uuid(),title text not null,text text not null,created_at timestamptz default now());
create table if not exists public.video_reviews(id uuid primary key default gen_random_uuid(),name text,video_url text,poster_url text,published boolean default false,created_at timestamptz default now());
alter table public.blog_posts add column if not exists subtitle text;alter table public.blog_posts add column if not exists video_url text;alter table public.media add column if not exists kind text default 'general';alter table public.appointments add column if not exists callback_time text;alter table public.appointments add column if not exists direction text;alter table public.appointments add column if not exists source_page text;alter table public.appointments add column if not exists status text default 'new';
alter table public.directions enable row level security;alter table public.education enable row level security;alter table public.menu_items enable row level security;alter table public.patient_resources enable row level security;alter table public.reply_templates enable row level security;alter table public.video_reviews enable row level security;
create policy "public directions" on public.directions for select to anon,authenticated using(published=true or public.is_admin());create policy "admin directions" on public.directions for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public education" on public.education for select to anon,authenticated using(true);create policy "admin education" on public.education for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public menu" on public.menu_items for select to anon,authenticated using(visible=true or public.is_admin());create policy "admin menu" on public.menu_items for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public resources" on public.patient_resources for select to anon,authenticated using(published=true or public.is_admin());create policy "admin resources" on public.patient_resources for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admin templates" on public.reply_templates for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public video reviews" on public.video_reviews for select to anon,authenticated using(published=true or public.is_admin());create policy "admin video reviews" on public.video_reviews for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into public.directions(title,description,icon,sort_order) values ('Лапароскопічна хірургія','Малотравматичні операції через невеликі розрізи.','01',1),('Хірургія гриж живота','Сучасне лікування пупкових, пахових та інших гриж.','02',2),('Проктологія','Діагностика та лікування проктологічних захворювань.','03',3),('Пластична хірургія','Естетичні та реконструктивні втручання.','04',4);
insert into public.education(period,title,description,sort_order) values ('2013–2017','Білоцерківський медичний фаховий коледж','',1),('2017–2022','Полтавський державний медичний університет','',2),('2022–2025','Інтернатура з хірургії — НМУ ім. О.О. Богомольця','',3);
insert into public.menu_items(label,href,sort_order) values ('Головна','#home',1),('Напрямки','#directions',2),('Послуги','#services',3),('Освіта','#education',4),('Блог','#blog',5),('Галерея','#gallery',6),('Важливо для пацієнта','#patient',7);
insert into public.site_settings(key,value) values ('hero_title','Маковецький Олександр Миколайович'),('hero_subtitle','Сучасна хірургія з увагою до деталей, зрозумілим планом лікування та супроводом пацієнта.'),('doctor_photo_url','assets/doctor.png'),('design_bg','#f6f3ed'),('design_paper','#fffefa'),('design_ink','#16211d'),('design_accent','#0f513f'),('design_radius','6px'),('design_container','1180px'),('design_section_space','92px') on conflict(key) do update set value=excluded.value;